2450	    console.log('[Main] Ending Meeting...');
2451	
2452	    // Reset Mouse Passthrough so the next meeting overlay starts fresh and focusable
2453	    if (this.overlayMousePassthrough) {
2454	      this.setOverlayMousePassthrough(false);
2455	    }
2456	
2457	    // ─── SYNCHRONOUS: things the user expects "right now" on Stop click ────
2458	    // Captures are deferred-stop wrappers (see SystemAudioCapture.stop /
2459	    // MicrophoneCapture.stop) — they flip the JS-side isRecording flag
2460	    // immediately so no new audio reaches STT, but defer the blocking native
2461	    // teardown to setImmediate. Returns within ~1ms.
2462	    this.systemAudioCapture?.stop();
2463	    this.microphoneCapture?.stop();
2464	
2465	    // Stop the default-output watcher — no point polling CoreAudio while
2466	    // there's no active capture to rebind.
2467	    this.stopDefaultOutputWatcher();
2468	
2469	    // Tell STT to mark the audio stream as ended; trailing finals will arrive
2470	    // over the next ~150ms while we're already returning to the renderer.
2471	    this.googleSTT?.finalize?.();
2472	    this.googleSTT_User?.finalize?.();
2473	
2474	    // Revert to Default Model — synchronous, no blocking I/O. The user
2475	    // expects the model UI to revert immediately on Stop.
2476	    try {
2477	      const { CredentialsManager } = require('./services/CredentialsManager');
2478	      const cm = CredentialsManager.getInstance();
2479	      const defaultModel = cm.getDefaultModel();
2480	      const all = [...(cm.getCurlProviders() || []), ...(cm.getCustomProviders() || [])];
2481	      console.log(`[Main] Reverting model to default: ${defaultModel}`);
2482	      this.processingHelper.getLLMHelper().setModel(defaultModel, all);
2483	      BrowserWindow.getAllWindows().forEach(win => {
2484	        if (!win.isDestroyed()) win.webContents.send('model-changed', defaultModel);
2485	      });
2486	    } catch (e) {
2487	      console.error('[Main] Failed to revert model:', e);
2488	    }
2489	
2490	    // ─── BACKGROUND: STT drain + meeting save + RAG embed ────────────────
2491	    // Critical: isMeetingActive stays TRUE during the 250ms grace window
2492	    // because main.ts:932 (stt.on('transcript')) drops segments when isActive
2493	    // is false — without that guarantee, the user's last words vanish.
2494	    //
2495	    // We expose the in-flight teardown as `_pendingTeardown` so a fast
2496	    // start→stop→start sequence awaits this completion in startMeeting()
2497	    // before booting a new session on the (still-shared) STT instances.
2498	    const ragManager = this.ragManager;
2499	    this._pendingTeardown = (async () => {
2500	      try {
2501	        // 1. Grace window for STT trailing finals (Google/Soniox/Deepgram all
2502	        //    reply to finalize() within 100–200ms). 250ms is conservative.
2503	        await new Promise(resolve => setTimeout(resolve, 250));
2504	
2505	        // 2. Tear down STT sockets now that finals have arrived.
2506	        this.googleSTT?.stop();
2507	        this.googleSTT_User?.stop();
2508	
2509	        // 3. Now safe to mark meeting inactive — STT delivered its finals.
2510	        this.isMeetingActive = false;
2511	        this.broadcastMeetingState();
2512	
2513	        // 4. Snapshot transcript + persist placeholder + queue title/summary LLM.
2514	        //    intelligenceManager.stopMeeting itself runs LLM in background.
2515	        const meetingId = await this.intelligenceManager.stopMeeting();
2516	
2517	        // 5. RAG cleanup — same logic as before, just inside the BG IIFE.
2518	        if (meetingId) {
2519	          if (ragManager) {
2520	            await ragManager.stopLiveIndexing();
2521	            console.log('[Main] Live RAG indexing stopped.');
2522	          }
2523	          await this.processCompletedMeetingForRAG(meetingId);
2524	          if (ragManager && !this.isMeetingActive) {
2525	            ragManager.deleteMeetingData('live-meeting-current');
2526	            console.log('[Main] JIT RAG provisional chunks cleaned up.');
2527	          } else if (this.isMeetingActive) {
2528	            console.log('[Main] New meeting started during cleanup — skipping live-meeting-current deletion.');
2529	          }
2530	        } else {
2531	          if (ragManager) {
2532	            await ragManager.stopLiveIndexing().catch(() => {});
2533	            if (!this.isMeetingActive) ragManager.deleteMeetingData('live-meeting-current');
2534	          }
2535	        }
2536	      } catch (err) {
2537	        console.error('[Main] Background meeting teardown failed:', err);
2538	      }
